                    if (input.charAt(i-1) == '(') {
                        result += stack.size();
    //                    System.out.println("## 레이저: 현재 스택 크기만큼 자름 (" + stack.size() + ") ##");
                    } else {
                        result += 1;
    //                    System.out.println("## 쇠막대기 끝 ##");
                    }
                }
    //            System.out.println("현재 스택 상태: " + stack);
    //            System.out.println("result: " + result);
    //            System.out.println("------------");
            }
            System.out.println(result);
        }
    }
