    import java.util.*;
    public static void main(String[] args) {
        // 입력
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        long[] arr = new long[n+1];
        // f(1) = f(2) = f(3) = 1이며 
        arr[1] = 1;
        arr[2] = 1;
        arr[3] = 1;

        // f(n) = f(n-1) + f(n-3)인 수열
        for (int i=4; i<=n; i++) {
            arr[i] = arr[i-1] + arr[i-3]
